/* Tech IA · unitat 4 «Imatge, veu i vídeo generats» (i4-1 … i4-4)
   Contingut propi de Numi. Com es genera una imatge (parelles imatge-text, difusió, prompts d'imatge, errors i estereotips,
   estils i artistes: i4-1); deepfakes i veus clonades (pistes, verificar, etiquetes, paraula clau, consentiment: i4-2);
   drets d'autor, Creative Commons, autoria de les imatges generades, entrenar amb obres d'altres i declarar l'ús (i4-3); i
   el projecte d'un còmic amb imatges generades i una fitxa de transparència (i4-4). Taller i4-5: un cartell amb un generador
   d'imatges de veritat (Canva per a l'Educació o el xat del centre), un prompt de 4 parts en tres versions, les condicions de
   l'eina i l'autoria declarada (passos iaext). A les sessions i4-1 … i4-4 el generador d'imatges és simulat:
   les «imatges» són dibuixos SVG propis que milloren segons el nivell del prompt (iaprompt). Persones, artistes, comptes i
   institucions: inventats. Fets amb data (llei europea d'IA, art. 50; Thaler v. Perlmutter): a les fonts de la guia. */
Object.assign(TBADGE, {
  i_pixel: { id: 'i_pixel', ico: '🎨', n: 'Del soroll a la imatge|Del ruido a la imagen', d: "Has entès com es genera una imatge i has escrit prompts d'imatge amb tema, estil, llum, format i límits.|Has entendido cómo se genera una imagen y has escrito prompts de imagen con tema, estilo, luz, formato y límites." },
  i_fake: { id: 'i_fake', ico: '🕵️', n: 'Antideepfakes|Antideepfakes', d: "Has après a verificar vídeos i àudios, a protegir-te de les veus clonades i a dir que no als deepfakes de persones reals.|Has aprendido a verificar vídeos y audios, a protegerte de las voces clonadas y a decir que no a los deepfakes de personas reales." },
  i_cc: { id: 'i_cc', ico: '©️', n: "Guardià/na de l'autoria|Guardián/a de la autoría", d: "Coneixes els drets d'autor i les llicències Creative Commons, i saps declarar què fa la IA i què fas tu.|Conoces los derechos de autor y las licencias Creative Commons, y sabes declarar qué hace la IA y qué haces tú." },
  i_author: { id: 'i_author', ico: '🏷️', n: 'Creador/a transparent|Creador/a transparente', d: "Has creat un còmic amb imatges generades, n'has decidit la història i n'has declarat l'autoria en una fitxa de transparència.|Has creado un cómic con imágenes generadas, has decidido su historia y has declarado su autoría en una ficha de transparencia." },
  i_genimg: { id: 'i_genimg', ico: '🖼️', n: 'Il·lustrador/a amb IA|Ilustrador/a con IA', d: "Has generat un cartell amb una IA de veritat, n'has millorat el prompt en tres versions, n'has llegit les condicions i n'has declarat l'autoria.|Has generado un cartel con una IA de verdad, has mejorado su prompt en tres versiones, has leído sus condiciones y has declarado su autoría." }
});

/* ---------- El generador d'imatges simulat: dibuixos propis per a cada tema i nivell de prompt (0 vague … 3 excel·lent) ---------- */
const I4W = (w, h, body) => `<svg viewBox="0 0 ${w} ${h}" style="display:block;width:100%;max-width:${w > h ? 210 : w === h ? 150 : 116}px;height:auto;margin:4px auto 8px;border-radius:12px;background:#fff;box-shadow:0 4px 14px rgba(0,0,0,.28)" aria-hidden="true">${body}</svg>`;
// detalls extra (purpurina) per al nivell excel·lent
const I4SPARK = svg => svg.replace(/<\/svg>$/, () => { const v = (svg.match(/viewBox="0 0 (\d+) (\d+)"/) || [0, 200, 200]).slice(1).map(Number); return [[.12, .1], [.88, .14], [.9, .86], [.1, .9]].map(([x, y], i) => { const cx = (v[0] * x).toFixed(0), cy = (v[1] * y).toFixed(0), r = 6 + (i % 2) * 2; return `<path d="M${cx} ${cy - r} L${+cx + r * .3} ${cy - r * .3} L${+cx + r} ${cy} L${+cx + r * .3} ${+cy + r * .3} L${cx} ${+cy + r} L${cx - r * .3} ${+cy + r * .3} L${cx - r} ${cy} L${cx - r * .3} ${cy - r * .3} Z" fill="#FDE68A" stroke="#F59E0B" stroke-width="1"/>`; }).join('') + '</svg>'; });
const I4grad = (id, stops) => `<defs><linearGradient id="${id}" x1="0" y1="0" x2="0" y2="1">${stops.map((c, i) => `<stop offset="${(i / (stops.length - 1)).toFixed(2)}" stop-color="${c}"/>`).join('')}</linearGradient></defs>`;
const I4tree = (x, y, s, c) => `<rect x="${x - 2.5 * s}" y="${y - 14 * s}" width="${5 * s}" height="${14 * s}" fill="#8B5A2B"/><circle cx="${x}" cy="${y - 21 * s}" r="${12 * s}" fill="${c}"/><circle cx="${x - 8 * s}" cy="${y - 15 * s}" r="${8 * s}" fill="${c}"/><circle cx="${x + 8 * s}" cy="${y - 15 * s}" r="${8 * s}" fill="${c}"/>`;
const I4bike = (x, y, s, c) => { const r = 8 * s, a = x - 12 * s, b = x + 12 * s, cy = y - r; return `<g fill="none" stroke-linecap="round" stroke-linejoin="round"><circle cx="${a}" cy="${cy}" r="${r}" stroke="#14204A" stroke-width="${2 * s}"/><circle cx="${b}" cy="${cy}" r="${r}" stroke="#14204A" stroke-width="${2 * s}"/>
  <path d="M${a} ${cy} L${x - 3 * s} ${cy - 11 * s} L${x + 8 * s} ${cy - 11 * s} L${b} ${cy} M${x - 3 * s} ${cy - 11 * s} L${x} ${cy} L${x + 8 * s} ${cy - 11 * s} M${x - 6 * s} ${cy - 14 * s} L${x - 1 * s} ${cy - 14 * s} M${x + 8 * s} ${cy - 11 * s} L${x + 6 * s} ${cy - 16 * s} L${x + 11 * s} ${cy - 16 * s}" stroke="${c}" stroke-width="${2.4 * s}"/></g>`; };
const I4gib = (x, y, t, c, sz = 12) => `<text x="${x}" y="${y}" text-anchor="middle" transform="rotate(-2 ${x} ${y})" style="font:900 ${sz}px Lexend,system-ui,sans-serif;fill:${c};letter-spacing:1px">${t}</text>`;
const I4note = (x, y, s, c) => `<g transform="translate(${x} ${y}) scale(${s})" fill="${c}"><ellipse cx="0" cy="0" rx="5" ry="3.6" transform="rotate(-20)"/><rect x="3.4" y="-16" width="1.8" height="16"/><path d="M5 -16 q6 2 5 9" stroke="${c}" stroke-width="1.8" fill="none"/></g>`;
const I4heart = (x, y, s, c) => `<path d="M${x} ${y + 12 * s} C${x - 20 * s} ${y - 2 * s} ${x - 10 * s} ${y - 18 * s} ${x} ${y - 7 * s} C${x + 10 * s} ${y - 18 * s} ${x + 20 * s} ${y - 2 * s} ${x} ${y + 12 * s} Z" fill="${c}"/>`;
const I4guitar = (x, y, s, c) => `<g transform="translate(${x} ${y}) rotate(-25) scale(${s})"><rect x="-3" y="-60" width="6" height="46" fill="#78350F"/><rect x="-5" y="-69" width="10" height="11" rx="2" fill="#78350F"/><circle cx="0" cy="-8" r="13" fill="${c}"/><circle cx="0" cy="12" r="17" fill="${c}"/><circle cx="0" cy="0" r="5" fill="#1E1B4B"/><rect x="-7" y="17" width="14" height="3" fill="#1E1B4B"/></g>`;
const I4cloud = (x, y, s, c = '#F1F5F9') => `<g fill="${c}"><circle cx="${x}" cy="${y}" r="${12 * s}"/><circle cx="${x + 14 * s}" cy="${y - 6 * s}" r="${14 * s}"/><circle cx="${x + 28 * s}" cy="${y}" r="${11 * s}"/><rect x="${x}" y="${y}" width="${28 * s}" height="${11 * s}"/></g>`;
const I4phone = (x, y, w, h, scr, extra = '') => `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${w * .16}" fill="#0E1332"/><rect x="${x + w * .08}" y="${y + h * .07}" width="${w * .84}" height="${h * .82}" rx="${w * .08}" fill="${scr}"/>${extra}`;
// un personatge: o = { hair, top, skin, long, cap, mouth: 'o'|'s'|'n', phone, raise, screen, line }
const I4kid = (x, y, s = 1, o = {}) => { const h = o.hair || '#3B82F6', t = o.top || '#FACC15', st = o.line ? ' stroke="#14204A" stroke-width="1.6"' : '';
  const mouth = o.mouth === 'o' ? '<ellipse cx="0" cy="1" rx="2.6" ry="3.2" fill="#7C2D12"/>' : o.mouth === 'n' ? '<path d="M-3 1 L3 1" stroke="#14204A" stroke-width="1.5"/>' : '<path d="M-4 -1 Q0 3.5 4 -1" stroke="#14204A" stroke-width="1.5" fill="none" stroke-linecap="round"/>';
  const back = o.long ? `<path d="M-15 14 Q-17 -24 0 -24 Q17 -24 15 14 Z" fill="${h}"/>` : '';
  const front = o.cap ? `<path d="M-14 -10 Q-13 -25 0 -25 Q13 -25 14 -10 Z" fill="${o.cap}"${st}/><rect x="6" y="-13" width="15" height="4" rx="2" fill="${o.cap}"/>` : o.long ? `<path d="M-13 -8 Q-12 -21 0 -21 Q12 -21 13 -8 Q6 -15 0 -14 Q-6 -15 -13 -8 Z" fill="${h}"/>` : `<path d="M-13 -5 Q-14 -23 0 -23 Q14 -23 13 -5 Q11 -14 4 -15 Q-2 -10 -9 -13 Q-12 -10 -13 -5 Z" fill="${h}"${st}/>`;
  const ph = o.raise ? `<path d="M12 16 L20 -16" stroke="${t}" stroke-width="7" stroke-linecap="round"/><rect x="13" y="-38" width="15" height="24" rx="3" fill="#0E1332"${st}/><rect x="15" y="-35" width="11" height="17" rx="2" fill="${o.screen || '#FEE2E2'}"/><circle cx="20.5" cy="-26.5" r="4.5" fill="none" stroke="#DC2626" stroke-width="1.6"/><path d="M17.3 -29.7 L23.7 -23.3" stroke="#DC2626" stroke-width="1.6"/><circle cx="20" cy="-13" r="4" fill="${o.skin || '#F2C9A0'}"/>`
    : o.phone ? `<rect x="11" y="4" width="10" height="16" rx="2" fill="#0E1332"${st}/><rect x="12.5" y="6" width="7" height="11" rx="1" fill="${o.screen || '#67E8F9'}"/><circle cx="12" cy="17" r="4" fill="${o.skin || '#F2C9A0'}"/>` : '';
  return `<g transform="translate(${x} ${y}) scale(${s})">${back}<path d="M-18 42 Q-18 11 0 11 Q18 11 18 42 Z" fill="${t}"${st}/><circle cx="0" cy="-7" r="13" fill="${o.skin || '#F2C9A0'}"${st}/>${front}<circle cx="-4.5" cy="-8" r="1.7" fill="#14204A"/><circle cx="4.5" cy="-8" r="1.7" fill="#14204A"/>${mouth}${ph}</g>`; };
const I4books = (x, y, w) => { let s = '', cx = x; const C = ['#EF4444', '#3B82F6', '#22C55E', '#F59E0B', '#8B5CF6', '#EC4899', '#14B8A6']; let i = 0; while (cx < x + w - 6) { const bw = 6 + (i * 7) % 5, bh = 22 + (i * 13) % 9; s += `<rect x="${cx}" y="${y - bh}" width="${bw}" height="${bh}" fill="${C[i % C.length]}"/>`; cx += bw + 1; i++; } return `<rect x="${x - 3}" y="${y}" width="${w + 6}" height="4" fill="#92400E"/>${s}`; };
const I4IMG = {
  tardor(lv, v = 0) {
    if (lv === 0) return I4W(200, 200, `<rect width="200" height="200" fill="#F8FAFC"/><ellipse cx="100" cy="166" rx="60" ry="8" fill="#E2E8F0"/>${I4tree(100, 166, 2.6, '#22C55E')}`);
    const mir = v ? ' transform="translate(150 0) scale(-1 1)"' : '';
    if (lv === 2) return I4W(150, 200, `<rect width="150" height="200" fill="#FED7AA"/><rect y="152" width="150" height="48" fill="#B45309"/><g${mir}>${I4tree(28, 154, 1.3, '#F97316')}${I4tree(120, 152, 1.6, '#EA580C')}${I4tree(76, 146, 1.1, '#F59E0B')}</g>${I4bike(76, 190, 1.1, '#2563EB')}${I4gib(75, 34, 'TΛRDØR RΞVIƧT', '#7C2D12', 14)}`);
    return I4W(150, 200, `${I4grad('i4gt' + v, ['#6D28D9', '#EC4899', '#F59E0B'])}<rect width="150" height="200" fill="url(#i4gt${v})"/><circle cx="${v ? 46 : 104}" cy="152" r="24" fill="#FDE68A" opacity=".9"/><rect y="152" width="150" height="48" fill="#7C2D12"/><g${mir}>${I4tree(24, 156, 1.4, '#C2410C')}${I4tree(128, 154, 1.7, '#9A3412')}${I4tree(98, 152, 1, '#EA580C')}</g>${I4bike(v ? 84 : 66, 192, 1.2, '#1E1B4B')}
      ${[[30, 70], [112, 88], [62, 110], [132, 46], [88, 60]].map(([x, y]) => `<ellipse cx="${v ? 150 - x : x}" cy="${y}" rx="3.2" ry="1.7" fill="#FDBA74" transform="rotate(30 ${v ? 150 - x : x} ${y})"/>`).join('')}`);
  },
  concert(lv) {
    if (lv === 0) return I4W(200, 200, `<rect width="200" height="200" fill="#F8FAFC"/>${I4note(92, 120, 3.4, '#14204A')}`);
    if (lv === 2) return I4W(150, 200, `<rect width="150" height="200" fill="#F3E8FF"/>${I4heart(110, 70, 1.2, '#F472B6')}${I4guitar(70, 132, 1.2, '#7C3AED')}${I4note(28, 110, 1.4, '#7C3AED')}${I4note(118, 150, 1.2, '#7C3AED')}${I4gib(75, 30, 'CΘNSΞRT SΘLIDΛRI', '#6D28D9', 12)}`);
    return I4W(150, 200, `${I4grad('i4gc', ['#4C1D95', '#BE185D'])}<rect width="150" height="200" fill="url(#i4gc)"/><rect width="150" height="44" fill="#000" opacity=".12"/>${I4heart(75, 118, 3.2, '#FDE68A')}${I4guitar(76, 126, 1, '#F97316')}${I4note(22, 96, 1.3, '#fff')}${I4note(124, 150, 1.3, '#fff')}${I4note(118, 74, 1, '#fff')}
      ${[[20, 178], [75, 186], [130, 178]].map(([x, y]) => `<circle cx="${x}" cy="${y}" r="4" fill="#FDE68A"/>`).join('')}`);
  },
  futur(lv) {
    if (lv === 0) return I4W(200, 200, `<rect width="200" height="200" fill="#E5E7EB"/>${[[10, 90], [44, 60], [78, 110], [112, 70], [146, 100]].map(([x, h]) => `<rect x="${x}" y="${190 - h}" width="30" height="${h}" fill="#9CA3AF"/>`).join('')}<rect y="190" width="200" height="10" fill="#6B7280"/>`);
    const bld = (x, w, h, g) => `<rect x="${x}" y="${170 - h}" width="${w}" height="${h}" fill="#F1F5F9" stroke="#CBD5E1"/>${g ? `<rect x="${x - 2}" y="${166 - h}" width="${w + 4}" height="6" rx="3" fill="#22C55E"/>` : ''}${Array.from({ length: Math.floor(h / 18) }, (_, i) => `<rect x="${x + 5}" y="${178 - h + i * 18}" width="${w - 10}" height="7" fill="#BAE6FD"/>`).join('')}`;
    const tram = (x, y) => `<rect x="${x}" y="${y}" width="56" height="18" rx="6" fill="#F97316"/>${[0, 1, 2, 3].map(i => `<rect x="${x + 5 + i * 13}" y="${y + 4}" width="9" height="7" rx="1.5" fill="#FFEDD5"/>`).join('')}<rect x="${x - 20}" y="${y + 19}" width="100" height="2" fill="#64748B"/>`;
    const solar = (x, y) => `<polygon points="${x},${y} ${x + 16},${y} ${x + 12},${y - 7} ${x - 4},${y - 7}" fill="#1D4ED8"/>`;
    if (lv === 2) return I4W(200, 200, `<rect width="200" height="200" fill="#BAE6FD"/><rect y="170" width="200" height="30" fill="#86EFAC"/>${bld(14, 40, 100, 1)}${bld(70, 46, 130, 1)}${bld(134, 44, 90, 1)}${solar(78, 40)}${solar(142, 80)}${tram(70, 174)}${I4tree(30, 184, .9, '#16A34A')}${I4tree(186, 184, .9, '#16A34A')}<rect x="120" y="22" width="70" height="18" rx="3" fill="#0F172A"/>${I4gib(155, 35, 'BΛRRI 2Ø7G', '#FDE047', 10)}`);
    return I4W(150, 200, `${I4grad('i4gf', ['#E0F2FE', '#BAE6FD', '#FEF3C7'])}<rect width="150" height="200" fill="url(#i4gf)"/><circle cx="118" cy="40" r="12" fill="#FDE68A"/><path d="M28 120 L28 64" stroke="#E2E8F0" stroke-width="3"/><g transform="translate(28 64)"><path d="M0 0 L0 -18 M0 0 L15 9 M0 0 L-15 9" stroke="#F8FAFC" stroke-width="3" stroke-linecap="round"/></g>
      <rect y="176" width="150" height="24" fill="#86EFAC"/>${bld(8, 34, 80, 1)}${bld(50, 40, 110, 1)}${bld(100, 40, 70, 1)}${solar(58, 60)}${solar(106, 100)}${tram(46, 178)}${I4tree(20, 190, .8, '#16A34A')}${I4tree(138, 190, .8, '#16A34A')}${I4bike(16, 200, .5, '#7C3AED')}`);
  },
  campanya(lv) {
    const lupa = (x, y, s, inner = '') => `<g transform="translate(${x} ${y}) scale(${s})"><circle cx="0" cy="0" r="16" fill="#fff" fill-opacity=".35" stroke="#0E1332" stroke-width="5"/>${inner}<path d="M11 11 L24 24" stroke="#0E1332" stroke-width="7" stroke-linecap="round"/></g>`;
    const play = (x, y, s) => `<polygon points="${x - 6 * s},${y - 8 * s} ${x - 6 * s},${y + 8 * s} ${x + 8 * s},${y}" fill="#fff"/>`;
    if (lv === 0) return I4W(200, 200, `<rect width="200" height="200" fill="#F8FAFC"/>${I4phone(72, 40, 56, 112, '#CBD5E1')}`);
    if (lv === 2) return I4W(150, 200, `<rect width="150" height="200" fill="#E0F2FE"/>${I4phone(45, 56, 60, 112, '#1E3A8A')}${play(75, 112, 1.3)}${lupa(96, 92, 1.1)}${I4gib(75, 32, 'VΞRIFFICΛ ΛNTS', '#0E7490', 13)}`);
    return I4W(150, 200, `${I4grad('i4gk', ['#0E7490', '#7C3AED'])}<rect width="150" height="200" fill="url(#i4gk)"/>${I4phone(45, 50, 60, 106, '#F8FAFC')}<rect x="52" y="66" width="46" height="34" rx="4" fill="#C7D2FE"/>${play(75, 83, 1)}<rect x="52" y="106" width="46" height="5" rx="2.5" fill="#CBD5E1"/><rect x="52" y="116" width="32" height="5" rx="2.5" fill="#CBD5E1"/>
      ${lupa(100, 92, 1.15, '<path d="M-7 0 L-2 5 L8 -6" stroke="#16A34A" stroke-width="4.5" fill="none" stroke-linecap="round"/>')}${['👤', '🔎', '🧭'].map((e, i) => `<circle cx="${33 + i * 42}" cy="180" r="13" fill="#fff" opacity=".9"/><text x="${33 + i * 42}" y="185" font-size="13" text-anchor="middle">${e}</text>`).join('')}`);
  },
  cicle(lv) {
    const mtn = (s = '') => `<polygon points="10,${130} 62,58 110,130" fill="#64748B"/>${s ? '<polygon points="52,72 62,58 72,72 66,70 62,74 57,70" fill="#F8FAFC"/>' : ''}`;
    const rain = (x, y) => [0, 1, 2, 3].map(i => `<path d="M${x + i * 9} ${y} l-4 10" stroke="#3B82F6" stroke-width="2.4" stroke-linecap="round"/>`).join('');
    if (lv === 0) return I4W(200, 200, `<rect width="200" height="200" fill="#F8FAFC"/>${I4cloud(70, 100, 1.6, '#CBD5E1')}`);
    const scene = (lab) => `<rect width="200" height="150" fill="#E0F2FE"/><circle cx="170" cy="26" r="14" fill="#FBBF24"/><rect x="110" y="112" width="90" height="38" fill="#2563EB"/><path d="M110 120 q8 -5 16 0 t16 0 t16 0 t16 0 t16 0" stroke="#93C5FD" stroke-width="2" fill="none"/>${mtn(1)}<rect y="130" width="110" height="20" fill="#86EFAC"/><path d="M62 130 Q80 124 96 132 Q104 136 112 126" stroke="#3B82F6" stroke-width="5" fill="none"/>
      ${I4cloud(56, 30, 1, '#F8FAFC')}${rain(62, 46)}<path d="M150 104 C152 80 140 60 112 40" stroke="#0E7490" stroke-width="2.2" stroke-dasharray="5 4" fill="none"/><path d="M112 40 l9 -1 m-9 1 l4 8" stroke="#0E7490" stroke-width="2.2" fill="none" stroke-linecap="round"/>${lab ? `${I4gib(150, 98, 'ΞVΛPØRΛCI', '#0E7490', 8)}${I4gib(46, 66, 'PLUJΛΛ', '#1D4ED8', 8)}${I4gib(80, 146, 'RIUU', '#1D4ED8', 8)}` : ''}`;
    return I4W(200, 150, scene(lv === 2));
  },
  kira1(lv) {
    if (lv === 0) return I4W(200, 200, `<rect width="200" height="200" fill="#F1F5F9"/>${I4kid(100, 108, 2.2, { hair: '#7C2D12', top: '#EF4444', long: true, mouth: 'n' })}`);
    const lines = Array.from({ length: 14 }, (_, i) => { const a = i / 14 * Math.PI * 2; return `<path d="M${(100 + Math.cos(a) * 60).toFixed(0)} ${(110 + Math.sin(a) * 60).toFixed(0)} L${(100 + Math.cos(a) * 120).toFixed(0)} ${(110 + Math.sin(a) * 120).toFixed(0)}" stroke="#BFDBFE" stroke-width="6"/>`; }).join('');
    if (lv === 2) return I4W(200, 200, `<rect width="200" height="200" fill="#E0F2FE"/>${lines}${I4kid(92, 116, 2.1, { phone: true, mouth: 'o' })}<ellipse cx="150" cy="36" rx="44" ry="22" fill="#fff" stroke="#14204A" stroke-width="2"/><path d="M132 54 L124 68 L142 56" fill="#fff" stroke="#14204A" stroke-width="2"/>${I4gib(150, 40, 'QUË ÉƧ ΛIXÖ?!', '#14204A', 10)}`);
    return I4W(200, 200, `<rect width="200" height="200" fill="#DBEAFE"/>${lines}${I4kid(92, 116, 2.1, { phone: true, mouth: 'o', line: true, screen: '#FDE68A' })}<path d="M140 120 l10 -6 M142 132 l12 0 M140 144 l10 6" stroke="#F59E0B" stroke-width="3" stroke-linecap="round"/><rect x="3" y="3" width="194" height="194" fill="none" stroke="#14204A" stroke-width="5"/>`);
  },
  kira3(lv) {
    const room = `<rect width="200" height="200" fill="#FEF3C7"/>${I4books(14, 52, 172)}${I4books(14, 96, 172)}<rect y="150" width="200" height="50" fill="#D6A16B"/>`;
    const laptop = (scr) => `<rect x="70" y="126" width="60" height="36" rx="3" fill="#0E1332"/><rect x="74" y="130" width="52" height="28" rx="2" fill="${scr}"/><rect x="62" y="162" width="76" height="5" rx="2" fill="#475569"/>`;
    if (lv === 0) return I4W(200, 200, `${room}${laptop('#94A3B8')}`);
    if (lv === 2) return I4W(200, 200, `${room}${I4kid(44, 118, 1.5)}${I4kid(156, 118, 1.5, { hair: '#111827', top: '#F97316', cap: '#16A34A' })}${laptop('#E2E8F0')}${I4gib(100, 148, 'FΛLƧ0?', '#DC2626', 11)}`);
    return I4W(200, 200, `${room}${I4kid(44, 118, 1.5, { line: true, mouth: 'n' })}${I4kid(156, 118, 1.5, { hair: '#111827', top: '#F97316', cap: '#16A34A', line: true })}${laptop('#E0F2FE')}<rect x="78" y="134" width="20" height="20" rx="2" fill="#fff"/><rect x="102" y="134" width="20" height="20" rx="2" fill="#fff"/><circle cx="112" cy="143" r="5" fill="none" stroke="#0E1332" stroke-width="2"/><path d="M115.5 146.5 L119 150" stroke="#0E1332" stroke-width="2"/><rect x="3" y="3" width="194" height="194" fill="none" stroke="#14204A" stroke-width="5"/>`);
  },
  kira4(lv) {
    const room = (t) => `<rect width="200" height="200" fill="#F1F5F9"/><rect x="18" y="14" width="164" height="62" rx="4" fill="#14532D" stroke="#92400E" stroke-width="4"/>${t || ''}${[24, 64, 136, 176].map((x, i) => `<circle cx="${x}" cy="186" r="15" fill="${['#111827', '#7C2D12', '#B45309', '#1F2937'][i]}"/><rect x="${x - 18}" y="194" width="36" height="12" rx="6" fill="${['#6366F1', '#10B981', '#F43F5E', '#0EA5E9'][i]}"/>`).join('')}`;
    if (lv === 0) return I4W(200, 200, `${room()}<rect x="40" y="120" width="120" height="10" fill="#A16207"/>`);
    if (lv === 2) return I4W(200, 200, room(I4gib(100, 50, 'NØ CØMPΛRTΞIXIƧ', '#F8FAFC', 11)) + I4kid(100, 120, 1.6, { raise: true }));
    return I4W(200, 200, room() + I4kid(96, 120, 1.6, { raise: true, line: true }) + `<rect x="3" y="3" width="194" height="194" fill="none" stroke="#14204A" stroke-width="5"/>`);
  }
};
// textos de cada nivell (ca, es): el generador simulat respon amb la imatge i un comentari
const I4CAP = {
  tardor: [["Imatge genèrica: un arbre verd qualsevol. No sap per a què la vols.", "Imagen genérica: un árbol verde cualquiera. No sabe para qué la quieres."], ["S'hi acosta: bosc i bici… però amb lletres inventades i sense la llum que volies. Afegeix-hi més peces.", "Se acerca: bosque y bici… pero con letras inventadas y sin la luz que querías. Añade más piezas."], ["Cartell vertical, llum de posta i sense text: queda espai per al títol, que el posaràs tu.", "Cartel vertical, luz de atardecer y sin texto: queda espacio para el título, que pondrás tú."], ["Excel·lent: hi ha tot el que has demanat, fins als detalls. El títol, posa'l tu, i digues que és generada amb IA.", "Excelente: está todo lo que has pedido, hasta los detalles. El título, ponlo tú, y di que está generada con IA."]],
  concert: [["Només una nota musical: no sap quin cartell vols.", "Solo una nota musical: no sabe qué cartel quieres."], ["Guitarra i cor… però amb lletres inventades i sense estil clar.", "Guitarra y corazón… pero con letras inventadas y sin estilo claro."], ["Cartell geomètric amb estil propi, sense cares ni text: el títol i la data els afegeixes tu.", "Cartel geométrico con estilo propio, sin caras ni texto: el título y la fecha los añades tú."], ["Excel·lent: estil propi i cap persona real. Afegeix-hi el títol i la data, i l'etiqueta «Fet amb IA».", "Excelente: estilo propio y ninguna persona real. Añade el título y la fecha, y la etiqueta «Hecho con IA»."]],
  futur: [["Una ciutat grisa qualsevol: no se sap que és el teu barri ni que és el futur.", "Una ciudad gris cualquiera: no se sabe que es tu barrio ni que es el futuro."], ["Hi ha terrats verds i tramvia… però també un rètol de lletres inventades.", "Hay azoteas verdes y tranvía… pero también un rótulo de letras inventadas."], ["El barri del futur tal com l'has descrit: verd, amb energia neta i espai al cel per al títol.", "El barrio del futuro tal como lo has descrito: verde, con energía limpia y espacio en el cielo para el título."], ["Excel·lent: el teu barri del futur, ple de detalls. Si el presentes al concurs, digues que és generat amb IA.", "Excelente: tu barrio del futuro, lleno de detalles. Si lo presentas al concurso, di que está generado con IA."]],
  campanya: [["Un mòbil qualsevol: no transmet cap missatge.", "Un móvil cualquiera: no transmite ningún mensaje."], ["Mòbil i lupa: la idea s'entén… però hi ha lletres inventades.", "Móvil y lupa: la idea se entiende… pero hay letras inventadas."], ["Clar i net: el vídeo, la lupa que el revisa i espai a dalt per al lema que escriuràs tu.", "Claro y limpio: el vídeo, la lupa que lo revisa y espacio arriba para el lema que escribirás tú."], ["Excel·lent: s'entén sense paraules. Escriu-hi el lema i afegeix l'etiqueta «Fet amb IA».", "Excelente: se entiende sin palabras. Escribe el lema y añade la etiqueta «Hecho con IA»."]],
  cicle: [["Només un núvol: falta tot el cicle.", "Solo una nube: falta todo el ciclo."], ["El cicle complet… amb etiquetes de lletres inventades.", "El ciclo completo… con etiquetas de letras inventadas."], ["Esquema original i net; les etiquetes, escriu-les tu. Crèdit: «Imatge generada amb IA (simulada) a partir del meu prompt; textos meus».", "Esquema original y limpio; las etiquetas, escríbelas tú. Crédito: «Imagen generada con IA (simulada) a partir de mi prompt; textos míos»."], ["Excel·lent: original i amb detalls. Crèdit: «Imatge generada amb IA (simulada) a partir del meu prompt; textos meus».", "Excelente: original y con detalles. Crédito: «Imagen generada con IA (simulada) a partir de mi prompt; textos míos»."]],
  kira1: [["Una noia qualsevol, sense mòbil: no és la Kira.", "Una chica cualquiera, sin móvil: no es Kira."], ["És la Kira… però el globus té lletres inventades.", "Es Kira… pero el globo tiene letras inventadas."], ["La Kira, sorpresa, en línia clara i amb espai per al globus. El text el posareu vosaltres.", "Kira, sorprendida, en línea clara y con espacio para el globo. El texto lo pondréis vosotros."], ["Excel·lent: la Kira tal com la volíeu. Guardeu aquesta descripció com a fitxa del personatge.", "Excelente: Kira tal como la queríais. Guardad esta descripción como ficha del personaje."]],
  kira3: [["Un ordinador en una sala: on són els personatges?", "Un ordenador en una sala: ¿dónde están los personajes?"], ["La Kira i en Leo a la biblioteca… amb lletres inventades a la pantalla.", "Kira y Leo en la biblioteca… con letras inventadas en la pantalla."], ["La mateixa Kira de la vinyeta 1, comprovant el vídeo amb en Leo. Coherent!", "La misma Kira de la viñeta 1, comprobando el vídeo con Leo. ¡Coherente!"], ["Excel·lent: coherent i amb el fons ple de detalls. El globus, escriviu-lo vosaltres.", "Excelente: coherente y con el fondo lleno de detalles. El globo, escribidlo vosotros."]],
  kira4: [["Una aula buida: falta la protagonista.", "Un aula vacía: falta la protagonista."], ["La Kira avisa la classe… però la pissarra té lletres inventades.", "Kira avisa a la clase… pero la pizarra tiene letras inventadas."], ["Final rodó: la Kira no comparteix el vídeo i avisa. Espai per al globus i cap persona real.", "Final redondo: Kira no comparte el vídeo y avisa. Espacio para el globo y ninguna persona real."], ["Excel·lent: final rodó i coherent. Ara l'etiqueta visible i la fitxa de transparència.", "Excelente: final redondo y coherente. Ahora la etiqueta visible y la ficha de transparencia."]]
};
const I4ANS = th => [0, 1, 2, 3].map(lv => { const s = lv === 3 ? I4SPARK(I4IMG[th](3)) : I4IMG[th]([0, 2, 3][lv]), [ca, es] = I4CAP[th][lv]; return `${s}<small style="display:block;line-height:1.35">🎨 ${ca}</small>|${s}<small style="display:block;line-height:1.35">🎨 ${es}</small>`; });
const I4IN = svg => svg.replace(/^<svg[^>]*>/, '').replace(/<\/svg>$/, '');
const I4ART = `<svg viewBox="0 0 316 200" style="display:block;width:100%;max-width:300px;height:auto;margin:0 auto" aria-hidden="true"><g>${I4IN(I4IMG.tardor(3, 0))}</g><g transform="translate(166 0)">${I4IN(I4IMG.tardor(3, 1))}</g></svg>`;
// zones per tocar damunt d'una imatge (percentatges de la imatge)
